class Whycodes < Formula
  desc "Terminal coding agent written in Rust"
  homepage "https://why.codes"
  version "0.6.25"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.6.25/whycodes-aarch64-apple-darwin.tar.gz"
      sha256 "bc524561b10f43a2502662abc060d6241adbd2f0c9a59fa081b8e8ac198d7b14"
